css:
/* Frappe's print styles force padding/top alignment/grey headers on every cell; reset them here. */
.print-format .pce th, .print-format .pce td { padding: 5px 6px !important; vertical-align: middle !important; color: #000 !important; }
.pce { font-family: "Arial", "Tajawal", sans-serif; font-size: 11px; color: #000; }
.pce table { width: 100%; border-collapse: collapse; table-layout: fixed; }

.pce-head td { border: none; }
.pce-logo { height: 64px; }
.pce-title { border: 1px solid #000 !important; text-align: center; font-weight: bold; font-size: 14px; }
.pce-form { text-align: center; padding-left: 24px !important; }
.pce-form-label { font-weight: bold; font-size: 11px; white-space: nowrap; margin-bottom: 4px; }
.pce-form-number { border: 1px solid #000; padding: 4px; font-size: 13px; font-weight: bold; }

.pce-info { margin-top: 12px; }
.pce-info th, .pce-info td { border: 1px solid #000; text-align: center; font-size: 12px; }
.pce-info th { font-weight: bold; background: #eeeeee !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.pce-info td.pce-gap { border: none; }

.pce-table { margin-top: 12px; border: 2px solid #000; }
.pce-table th, .pce-table td { border: 1px solid #000; word-wrap: break-word; }
.pce-table thead th { text-align: center; font-weight: bold; font-size: 11px; line-height: 1.3; background: #eeeeee !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.pce-table tfoot th { font-weight: bold; font-size: 12px; border-top: 2px solid #000; }
.pce-table .c { text-align: center; }
.pce-table .r { text-align: right; }
.pce-table .nowrap { white-space: nowrap; font-size: 10px; }

.pce-sign { margin-top: 28px; }
.pce-sign td { border: none; padding: 18px 4px 2px !important; vertical-align: bottom !important; }
.pce-sign .lbl { font-weight: bold; white-space: nowrap; }
.pce-sign .line { border-bottom: 1px solid #000; }
.pce-sign .sep td { padding: 14px 0 0 !important; border-bottom: 1px solid #000; }

.pce-payment { margin-top: 26px; }
.pce-payment td { border: none; height: 26px; }
.pce-payment .box { border: 1px solid #000; text-align: center; }
.pce-payment .lbl { font-weight: bold; }
.pce-table .nowrap-head { white-space: nowrap; }
